def t1(df: pd.DataFrame):
    df = df.copy()
    num_cols = ['masfem', 'masfem_mturk', 'gender_mf', 'alldeaths', 'ndam15',
        'wind', 'category', 'min', 'year', 'elapsedyrs']
    column_mapping = {}
    for c in num_cols:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors='coerce')
            column_mapping[frozenset([c])] = c
    return TransformDataReturn(
        df=df,
        column_mapping=column_mapping,
        transform_verb='derive'
    )

def t2(df: pd.DataFrame):
    if 'alldeaths' in df.columns:
        df['log_alldeaths'] = np.log1p(df['alldeaths'])
    else:
        df['log_alldeaths'] = np.nan
    return TransformDataReturn(
        df=df,
        column_mapping={frozenset(['alldeaths']): 'log_alldeaths'},
        transform_verb='derive'
    )

def t3(df: pd.DataFrame):
    if 'ndam15' in df.columns:
        df['log_ndam15'] = np.log1p(df['ndam15'])
    else:
        df['log_ndam15'] = np.nan
    return TransformDataReturn(
        df=df,
        column_mapping={frozenset(['ndam15']): 'log_ndam15'},
        transform_verb='derive'
    )

def t4(df: pd.DataFrame):
    if 'masfem' in df.columns:
        mean_m = df['masfem'].mean()
        std_m = df['masfem'].std(ddof=0)
        df['masfem_z'] = (df['masfem'] - mean_m) / (std_m if std_m != 0 else 1.0)
    else:
        df['masfem_z'] = np.nan
    return TransformDataReturn(
        df=df,
        column_mapping={frozenset(['masfem']): 'masfem_z'},
        transform_verb='derive'
    )

def t5(df: pd.DataFrame):
    if 'masfem_mturk' in df.columns:
        mean_mt = df['masfem_mturk'].mean()
        std_mt = df['masfem_mturk'].std(ddof=0)
        df['masfem_mturk_z'] = (df['masfem_mturk'] - mean_mt) / (std_mt if std_mt != 0 else 1.0)
    else:
        df['masfem_mturk_z'] = np.nan
    return TransformDataReturn(
        df=df,
        column_mapping={frozenset(['masfem_mturk']): 'masfem_mturk_z'},
        transform_verb='derive'
    )

def t6(df: pd.DataFrame):
    if 'gender_mf' in df.columns:
        df['female_name'] = pd.to_numeric(df['gender_mf'], errors='coerce').astype(float)
    else:
        df['female_name'] = np.nan
    return TransformDataReturn(
        df=df,
        column_mapping={frozenset(['gender_mf']): 'female_name'},
        transform_verb='derive'
    )

def t7(df: pd.DataFrame):
    if 'year' in df.columns:
        df['year_c'] = df['year'] - df['year'].median()
    else:
        df['year_c'] = np.nan
    return TransformDataReturn(
        df=df,
        column_mapping={frozenset(['year']): 'year_c'},
        transform_verb='derive'
    )

def t8(df: pd.DataFrame):
    required_for_model = ['masfem_z', 'wind', 'category', 'min', 'year_c',
        'elapsedyrs', 'source']
    present_required = [c for c in required_for_model if c in df.columns]
    if len(present_required) > 0:
        df = df.dropna(subset=present_required)
        return TransformDataReturn(
            df=df,
            column_mapping={frozenset(present_required): 'ALL'},
            transform_verb='filter'
        )
    # no required columns present, no-op
    return TransformDataReturn(
        df=df,
        column_mapping={},
        transform_verb='filter'
    )

